func (p *parser) run() (stmts []map[string]any, err error) {
	defer func() {
		if r := recover(); r != nil {
			if os.Getenv("PANICSTACK") != "" {
				debug.PrintStack()
			}
			fmt.Fprintln(os.Stderr, "PANIC:", r)
			err = fmt.Errorf("%v", r)
		}
	}()
	return p.parseTopLevel(), nil
